<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Auth;use App\Security;use App\Admin;
$user=Auth::requireUser();if(($user['role_name']??'')!=='super_admin'){http_response_code(403);exit('هذه الصفحة متاحة للمدير الرئيسي فقط.');}$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='save'){$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$role=(string)($_POST['role']??'staff');$password=(string)($_POST['password']??'');$active=isset($_POST['is_active'])?1:0;if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['manager','staff'],true))throw new RuntimeException('تحقق من الاسم والبريد والدور. لا يمكن إنشاء مدير رئيسي من هذه الشاشة.');$q=$pdo->prepare("SELECT id FROM roles WHERE name=?");$q->execute([$role]);$roleId=(int)$q->fetchColumn();if(!$roleId)throw new RuntimeException('الدور غير موجود.');if($id){if($password!==''){if(strlen($password)<12)throw new RuntimeException('كلمة المرور يجب ألا تقل عن 12 حرفاً.');$pdo->prepare("UPDATE users SET name=?,email=?,role_id=?,is_active=?,password_hash=? WHERE id=?")->execute([$name,$email,$roleId,$active,password_hash($password,PASSWORD_DEFAULT),$id]);}else{$pdo->prepare("UPDATE users SET name=?,email=?,role_id=?,is_active=? WHERE id=?")->execute([$name,$email,$roleId,$active,$id]);}}else{if(strlen($password)<12)throw new RuntimeException('كلمة المرور الأولية يجب ألا تقل عن 12 حرفاً.');$q=$pdo->prepare("INSERT INTO users(name,email,role_id,is_active,password_hash) VALUES(?,?,?,?,?)");$q->execute([$name,$email,$roleId,$active,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();}Admin::audit('user.save','user',$id,['role'=>$role]);header('Location: users.php?saved=1');exit;}
 if($action==='permissions'){if(!$id)throw new RuntimeException('المستخدم غير صحيح.');$pdo->beginTransaction();$pdo->prepare("DELETE FROM user_permissions WHERE user_id=?")->execute([$id]);$all=$pdo->query("SELECT id FROM permissions")->fetchAll(PDO::FETCH_COLUMN);$selected=array_map('intval',$_POST['permission_ids']??[]);$insert=$pdo->prepare("INSERT INTO user_permissions(user_id,permission_id,allowed) VALUES(?,?,?)");foreach($all as $pid){$insert->execute([$id,(int)$pid,in_array((int)$pid,$selected,true)?1:0]);}$pdo->commit();Admin::audit('user.permissions','user',$id);header('Location: users.php?permissions_saved=1');exit;}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر حفظ المستخدم. قد يكون البريد مستخدماً بالفعل.';}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name<>'super_admin'");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$permUser=null;$permissions=[];if(isset($_GET['permissions'])){$q=$pdo->prepare("SELECT id,name,email FROM users WHERE id=? AND role_id<>(SELECT id FROM roles WHERE name='super_admin')");$q->execute([(int)$_GET['permissions']]);$permUser=$q->fetch()?:null;if($permUser){$permissions=$pdo->query("SELECT id,permission_key,label FROM permissions ORDER BY permission_key")->fetchAll();$q=$pdo->prepare("SELECT permission_id FROM user_permissions WHERE user_id=? AND allowed=1");$q->execute([$permUser['id']]);$granted=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}}
$users=$pdo->query("SELECT u.id,u.name,u.email,u.is_active,u.created_at,r.name role_name,r.label role_label FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name<>'super_admin' ORDER BY u.id DESC")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>المستخدمون والصلاحيات</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1100px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:20px;margin:16px 0}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.fields label{display:block}.fields input,.fields select{width:100%;padding:10px;background:#080808;color:white;border:1px solid #49371c;border-radius:8px;font:inherit}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:10px;border-bottom:1px solid #342718}.scroll{overflow:auto}.table{min-width:700px}.perms{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.perms label{padding:8px;border:1px solid #49371c;border-radius:8px}@media(max-width:600px){.fields,.perms{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>المستخدمون والصلاحيات</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice">تم حفظ المستخدم.</div><?php endif;?><?php if(isset($_GET['permissions_saved'])):?><div class="notice">تم تحديث صلاحيات المستخدم.</div><?php endif;?><section class="panel"><h2><?=$edit?'تعديل مستخدم':'إنشاء مستخدم'?></h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="fields"><label>الاسم<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>البريد الإلكتروني<input name="email" type="email" required value="<?=e($edit['email']??'')?>"></label><label>الدور<select name="role"><option value="staff" <?=($edit['role_name']??'')==='staff'?'selected':''?>>موظف</option><option value="manager" <?=($edit['role_name']??'')==='manager'?'selected':''?>>مدير مساعد</option></select></label><label>كلمة المرور <?= $edit?'(اتركها فارغة للإبقاء عليها)':'' ?><input name="password" type="password" minlength="12" <?=$edit?'':'required'?> autocomplete="new-password"></label><label><input type="checkbox" name="is_active" style="width:auto" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> حساب نشط</label></div><p><button class="btn btn-gold">حفظ المستخدم</button></p></form></section><?php if($permUser):?><section class="panel"><h2>صلاحيات: <?=e($permUser['name'])?></h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="permissions"><input type="hidden" name="id" value="<?=(int)$permUser['id']?>"><div class="perms"><?php foreach($permissions as $p):?><label><input type="checkbox" name="permission_ids[]" value="<?=(int)$p['id']?>" <?=in_array((int)$p['id'],$granted,true)?'checked':''?>> <?=e($p['label'])?></label><?php endforeach;?></div><p><button class="btn btn-gold">حفظ الصلاحيات المحددة</button></p><small>تحديد الصلاحية يمنحها صراحةً، وإلغاء التحديد يمنعها حتى لو كان دور المستخدم يمنحها.</small></form></section><?php endif;?><section class="panel"><h2>حسابات الفريق</h2><div class="scroll"><table class="table"><thead><tr><th>الاسم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role_label'])?></td><td><?=((int)$u['is_active']?'نشط':'معطل')?></td><td><a class="btn btn-outline" href="?edit=<?=(int)$u['id']?>">تعديل</a> <a class="btn btn-outline" href="?permissions=<?=(int)$u['id']?>">الصلاحيات</a></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>